CREATE TABLE "HealthPharmacyKit" (id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HealthPharmacyKitItem" (id TEXT PRIMARY KEY,"kitId" TEXT NOT NULL REFERENCES "HealthPharmacyKit"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"materialId" TEXT NOT NULL REFERENCES "Material"(id) ON DELETE RESTRICT ON UPDATE CASCADE,quantity DOUBLE PRECISION NOT NULL,UNIQUE("kitId","materialId"));
CREATE TABLE "HealthPharmacyKitDelivery" (id TEXT PRIMARY KEY,"kitId" TEXT NOT NULL REFERENCES "HealthPharmacyKit"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"kitVersion" INTEGER NOT NULL,"patientId" TEXT NOT NULL REFERENCES "Patient"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"warehouseId" TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'GENERATED',criteria JSONB NOT NULL,"sourceSnapshot" JSONB NOT NULL,"receiverPersonId" TEXT,"receiverRelationship" TEXT,"generatedByUsuarioId" TEXT NOT NULL,"deliveredAt" TIMESTAMP(3),"deliveredByUsuarioId" TEXT,"returnedAt" TIMESTAMP(3),"returnedByUsuarioId" TEXT,"idempotencyKey" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "HealthPharmacyKitDelivery_patientId_status_idx" ON "HealthPharmacyKitDelivery"("patientId",status);
CREATE INDEX "HealthPharmacyKitDelivery_warehouseId_status_idx" ON "HealthPharmacyKitDelivery"("warehouseId",status);
CREATE TABLE "HealthPharmacyKitDeliveryItem" (id TEXT PRIMARY KEY,"deliveryId" TEXT NOT NULL REFERENCES "HealthPharmacyKitDelivery"(id) ON DELETE RESTRICT ON UPDATE CASCADE,"materialId" TEXT NOT NULL REFERENCES "Material"(id) ON DELETE RESTRICT ON UPDATE CASCADE,quantity DOUBLE PRECISION NOT NULL,"prescriptionItemId" TEXT,"stockId" TEXT,"movementId" TEXT UNIQUE,"reversalMovementId" TEXT UNIQUE,UNIQUE("deliveryId","materialId"));
CREATE TABLE "HealthPharmacyKitEvent" (id TEXT PRIMARY KEY,"deliveryId" TEXT NOT NULL REFERENCES "HealthPharmacyKitDelivery"(id) ON DELETE RESTRICT ON UPDATE CASCADE,status TEXT NOT NULL,reason TEXT NOT NULL,"actorUsuarioId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "MedicineDispensation" ADD COLUMN "kitDeliveryItemId" TEXT UNIQUE REFERENCES "HealthPharmacyKitDeliveryItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HealthPharmacyKitDelivery" ADD FOREIGN KEY ("warehouseId") REFERENCES "Warehouse"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD FOREIGN KEY ("receiverPersonId") REFERENCES "Person"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "HealthPharmacyKitDeliveryItem" ADD FOREIGN KEY ("prescriptionItemId") REFERENCES "HealthPrescriptionItem"(id) ON DELETE RESTRICT ON UPDATE CASCADE, ADD FOREIGN KEY ("stockId") REFERENCES "MaterialStock"(id) ON DELETE RESTRICT ON UPDATE CASCADE;
